const item = $input.first().json;
const headers = item.headers ?? {};
const provided = String(headers['x-n8n-secret'] ?? headers['X-N8N-Secret'] ?? '');
const expected = String($env.N8N_WEBHOOK_SECRET ?? '');
if (!expected) throw new Error('N8N_WEBHOOK_SECRET is not configured in n8n');
if (provided.length !== expected.length) throw new Error('Unauthorized: bad webhook secret');
let diff = 0;
for (let i = 0; i < expected.length; i++) diff |= provided.charCodeAt(i) ^ expected.charCodeAt(i);
if (diff !== 0) throw new Error('Unauthorized: bad webhook secret');
return [$input.first()];

const hasHf = Boolean($env.HF_TOKEN);
return [{ json: { imageGenAvailable: hasHf,
  note: hasHf ? 'HF image quota assumed; honor 429s' : 'no HF token — brief only' } }];

const wh = $('webhook-entry').first().json;
const body = wh.body ?? wh;
const p = body.product ?? {}, s = body.script ?? {};
// Visual brief per scene (§8): 9:16 vertical, original AI visuals only,
// product-accurate to verified facts, never presented as real testing.
const scenes = ['hook', 'intro', 'features'].map((sc, i) => ({
  scene: sc, aspect: '9:16', index: i,
  brief: `Original AI product visual, vertical 9:16, dark clean studio background, ` +
    `product-accurate to verified facts for "${p.name ?? 'product'}", no text overlays ` +
    `in image, no invented ports/logos/capabilities`,
  source: 'ai-generated-original',
}));
return [{ json: { product: p, script: s, visualBrief: scenes,
  assetsStatus: 'brief-ready' } }];

const j = $input.first().json;
const attest = {
  originalAiOnly: True, noExternalFootage: True, noCompetitorReuse: True,
  productAccurate: True, notPresentedAsRealTesting: True,
};
// Hard attestation (§8): any False would REJECT — all True by construction.
return [{ json: { ...j, attest, attested: Object.values(attest).every(Boolean) } }];

const j = $input.first().json;
return [{ json: { product: { ...j.product }, script: j.script,
  visualBrief: j.visualBrief, assetsStatus: 'brief-ready',
  todo: 'MODEL CALL TODO: execute brief via HF FLUX.1 (or backend job) — only then set ASSETS_READY' } }];
